<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {NButton,NSelect,NConfigProvider,zhCN} from 'naive-ui'
import {api,money,type User,type Account,type Location,type Transfer} from './api/funds'
import CatalogView from './views/CatalogView.vue'
import TransfersView from './views/TransfersView.vue'
import UsersView from './views/UsersView.vue'
import TransferEditor from './components/TransferEditor.vue'
const user=ref<User|null>(null),users=ref<User[]>([]),selected=ref<string|null>(null),accounts=ref<Account[]>([]),locations=ref<Location[]>([]),transfers=ref<Transfer[]>([]),total=ref(0),tab=ref('accounts'),error=ref(''),notice=ref(''),busy=ref(false),showTransfer=ref(false),opening=ref(false)
const trusted=computed(()=>user.value?.role==='trusted'||user.value?.role==='admin')
const roles={admin:'管理员',trusted:'受信任用户',untrusted:'普通用户'}
const nav=computed(()=>[{value:'accounts',label:'资金与记账对象'},{value:'transfers',label:'划转记录'},...(trusted.value?[{value:'approvals',label:'审批'}]:[]),{value:'locations',label:'存货地点'},...(user.value?.role==='admin'?[{value:'users',label:'用户管理'}]:[])])
async function refresh(){if(!user.value)return;busy.value=true;error.value='';try{const [a,l,t,s]=await Promise.all([api.accounts(),api.locations(),api.transfers(),api.summary()]);accounts.value=a;locations.value=l;transfers.value=t;total.value=s.total_minor}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function identities(){users.value=await api.users()}
async function login(){if(!selected.value)return;busy.value=true;error.value='';try{await api.login(selected.value);user.value=await api.me();tab.value='accounts';notice.value='开发账号已切换';await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function logout(){try{await api.logout();user.value=null;accounts.value=[];locations.value=[];transfers.value=[];notice.value='已退出'}catch(e){error.value=(e as Error).message}}
async function permissionChanged(){await identities();try{user.value=await api.me();if(!nav.value.some(n=>n.value===tab.value))tab.value='accounts';await refresh()}catch(e){user.value=null;error.value=(e as Error).message}}
function create(isOpening=false){opening.value=isOpening;showTransfer.value=true}
onMounted(async()=>{try{await identities();try{user.value=await api.me();selected.value=user.value.id}catch{}await refresh()}catch(e){error.value=(e as Error).message}})
</script>
<template><NConfigProvider :locale="zhCN"><div class="shell"><header><div><h1>FGAS 资金工作台</h1><p>开发环境 / 单组织 / 人民币</p></div><div class="identity"><strong>当前开发账号：{{user?`${user.display_name}（${roles[user.role]}）`:'未登录'}}</strong><div class="login"><NSelect v-model:value="selected" placeholder="选择开发账号" :options="users.filter(u=>u.active).map(u=>({label:`${u.display_name} (${u.id})`,value:u.id}))"/><NButton :loading="busy" @click="login">切换 / 登录</NButton><NButton v-if="user" @click="logout">退出</NButton></div></div></header><p v-if="error" class="banner error" role="alert">{{error}}</p><p v-if="notice" class="banner success" role="status">{{notice}}</p><template v-if="user"><nav><button v-for="item in nav" :key="item.value" :class="{active:tab===item.value}" @click="tab=item.value">{{item.label}}</button></nav><main><template v-if="tab==='accounts'"><section class="summary"><div><span>资金账面余额</span><strong>¥ {{money(total)}}</strong><small>仅汇总标记为资金对象的真实账面余额。</small></div><div class="actions"><NButton @click="refresh" :loading="busy">刷新</NButton><NButton @click="create(true)">期初资金</NButton><NButton type="primary" @click="create()">新建划转</NButton></div></section><CatalogView mode="accounts" :accounts="accounts" :locations="locations" :editable="trusted" @changed="refresh"/></template><TransfersView v-else-if="tab==='transfers'||tab==='approvals'" :items="transfers" :accounts="accounts" :approvals="tab==='approvals'" :trusted="trusted" @changed="refresh" @notice="notice=$event"/><CatalogView v-else-if="tab==='locations'" mode="locations" :accounts="accounts" :locations="locations" :editable="trusted" @changed="refresh"/><UsersView v-else-if="tab==='users'&&user.role==='admin'" @changed="permissionChanged"/></main><TransferEditor :key="user.id" :show="showTransfer" :accounts="accounts" :opening="opening" @close="showTransfer=false" @saved="notice='划转'+$event;refresh()"/></template><main v-else><h2>登录开发账号开始使用</h2><p>管理员与受信任用户可过账和审批；普通用户提交的划转进入待审批。</p></main><footer>开发原型。存货数量、债务跟踪和生产认证尚未实现。</footer></div></NConfigProvider></template>
